const LON0 = 24.0;
const LAT1 = 56.0;
const SCALE = 24.0;
const COS = Math.cos((40 * Math.PI) / 180);

/** Longitude/latitude to base-map units. */
export const projectCentralAsia = (lon: number, lat: number): [number, number] => [
  (lon - LON0) * COS * SCALE,
  (LAT1 - lat) * SCALE,
];

/** Base-map units back to longitude/latitude (for taps on the map). */
export const unprojectCentralAsia = (x: number, y: number): [number, number] => [
  LON0 + x / (COS * SCALE),
  LAT1 - y / SCALE,
];

/** Base-map units for one kilometre (north-south), for the scale bar. */
export const CENTRAL_ASIA_UNITS_PER_KM = SCALE / 111.2;
